"use client";

import { useState } from "react";

export default function ListWithDrawer({
  title,
  columns,
  items,
  newLabel = "New",
}: {
  title: string;
  columns: { key: string; label: string; mono?: boolean }[];
  items: any[];
  newLabel?: string;
}) {
  const [open, setOpen] = useState(false);
  const [row, setRow] = useState<any>(null);

  return (
    <>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <h1 style={{ margin: 0 }}>{title}</h1>
        <button className="btn" onClick={() => { setRow({}); setOpen(true); }}>
          + {newLabel}
        </button>
      </div>

      <div className="panel" style={{ padding: 0, marginTop: 12 }}>
        <table className="table">
          <thead>
            <tr>{columns.map(c => <th key={c.key}>{c.label}</th>)}</tr>
          </thead>
          <tbody>
            {items.map((r, i) => (
              <tr key={i} className="rowHover" onClick={() => { setRow(r); setOpen(true); }}>
                {columns.map(c => (
                  <td key={c.key} className={c.mono ? "mono" : ""}>{r[c.key]}</td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {open && (
        <div className="drawerWrap">
          <div className="drawerBackdrop" onClick={() => setOpen(false)} />
          <div className="drawer">
            <div style={{ display: "flex", justifyContent: "space-between" }}>
              <h2>{row?.id ? "Edit" : "New"} {title.slice(0, -1)}</h2>
              <button className="btnGhost" onClick={() => setOpen(false)}>Close</button>
            </div>
            <div className="hr" />
            <div>
              <div className="fieldLabel">Name</div>
              <input className="input" defaultValue={row?.name || ""} />
            </div>
          </div>
        </div>
      )}
    </>
  );
}
